stubs['com/joyboost/moneyboost/BannerPreloadTest.java']='''package com.joyboost.moneyboost;
import java.lang.reflect.*;import com.google.android.libraries.ads.mobile.sdk.banner.*;import com.google.android.libraries.ads.mobile.sdk.common.*;
public class BannerPreloadTest{static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static void tick(MoneyBoostBannerAdapter a,int count)throws Exception{Field f=a.getClass().getDeclaredField("refreshTick");f.setAccessible(true);Runnable t=(Runnable)f.get(a);for(int i=0;i<count;i++){android.os.SystemClock.now+=1000;t.run();}}
static MoneyBoostBannerAdapter make(){MoneyBoostBannerAdapter a=new MoneyBoostBannerAdapter();a.MoneyBoost_activity=new android.app.Activity();a.MoneyBoost_ad_unit="unit";a.MoneyBoostInitBannerAdapter();return a;}
public static void main(String[] args)throws Exception{
 MoneyBoostBannerAdapter a=make();MoneyBoostMediationManager.allowed=false;a.MoneyBoostLoadBannerView();check(BannerAdPreloader.starts==0,"consent");MoneyBoostMediationManager.allowed=true;
 BannerAdPreloader.fail=true;try{a.MoneyBoostLoadBannerView();}catch(RuntimeException expected){}BannerAdPreloader.fail=false;a.MoneyBoostLoadBannerView();a.MoneyBoostLoadBannerView();check(BannerAdPreloader.starts==2,"duplicate registration or rollback");String normalId=BannerAdPreloader.id;
 BannerAdPreloader.available=true;BannerAdPreloader.callback.onAdPreloaded(normalId,new ResponseInfo());check(BannerAdPreloader.polls==0,"eager poll");a.MoneyBoostShowBannerView();check(BannerAdPreloader.polls==1&&a.MoneyBoostIsVisible(),"show not registered");BannerAd first=BannerAdPreloader.last;tick(a,40);check(BannerAdPreloader.polls==1,"rotated before first real impression");first.callback.onAdImpression();
 BannerAdPreloader.available=true;a.MoneyBoostHideBannerView();tick(a,100);check(BannerAdPreloader.polls==1,"refresh while hidden");a.MoneyBoostShowBannerView();tick(a,29);check(BannerAdPreloader.polls==1,"refresh too soon");tick(a,1);check(BannerAdPreloader.polls==2&&first.destroyed==1,"30s refresh absent or double destroy");
 first.callback.onAdPaid(new AdValue());check(MoneyBoostFirebaseManager.paid==0,"stale paid event");BannerAd second=BannerAdPreloader.last;second.callback.onAdImpression();second.callback.onAdPaid(new AdValue());check(MoneyBoostFirebaseManager.paid==1,"paid event absent");
 MoneyBoostMediationManager.foreground=false;BannerAdPreloader.available=true;tick(a,50);check(BannerAdPreloader.polls==2,"background refresh");MoneyBoostMediationManager.foreground=true;BannerAdPreloader.available=false;tick(a,30);check(BannerAdPreloader.polls==2&&a.MoneyBoostIsVisible()&&second.destroyed==0,"no-fill removed displayed banner");BannerAdPreloader.available=true;tick(a,1);check(BannerAdPreloader.polls==3,"refill not consumed");
 BannerAd third=BannerAdPreloader.last;third.callback.onAdImpression();AdView.failRegister=true;BannerAdPreloader.available=true;tick(a,30);BannerAd failed=BannerAdPreloader.last;check(a.MoneyBoostIsVisible()&&third.destroyed==0&&failed.destroyed==1,"render failure blanked bottom banner");int paid=MoneyBoostFirebaseManager.paid;failed.callback.onAdPaid(new AdValue());check(MoneyBoostFirebaseManager.paid==paid,"failed replacement reported paid");AdView.failRegister=false;BannerAdPreloader.available=true;tick(a,1);check(third.destroyed==1&&a.MoneyBoostIsVisible(),"render recovery lost bottom banner");
 int starts=BannerAdPreloader.starts;BannerAdPreloader.callback.onAdFailedToPreload(normalId,new LoadAdError());a.MoneyBoostLoadBannerView();check(BannerAdPreloader.starts==starts,"manual network retry");
 MoneyBoostBannerAdapter c=make();c.MoneyBoostLoadCollapsibleBannerView();check(!normalId.equals(BannerAdPreloader.id)&&BannerAdPreloader.request.collapsible,"fold shares pool or missing extras");BannerAdPreloader.available=true;c.MoneyBoostShowBannerView();check(android.view.ViewGroup.lastAttachedVisibility==android.view.View.VISIBLE,"fold attached hidden, losing expansion");int polls=BannerAdPreloader.polls;BannerAdPreloader.available=true;tick(c,100);check(BannerAdPreloader.polls==polls,"fold auto-expanded on timer");BannerAd consumed=BannerAdPreloader.last;int startsBefore=BannerAdPreloader.starts,destroysBefore=BannerAdPreloader.destroys;
 c.MoneyBoostReleaseDisplayedBanner();check(consumed.destroyed==1&&!c.MoneyBoostIsVisible(),"consumed fold renderer not released");
 check(BannerAdPreloader.destroys==destroysBefore&&c.MoneyBoostIsLoaded(),"fold close lost preloaded next inventory");
 c.MoneyBoostLoadCollapsibleBannerView();c.MoneyBoostShowBannerView();
 check(BannerAdPreloader.starts==startsBefore&&BannerAdPreloader.polls==polls+1&&c.MoneyBoostIsVisible(),"next opportunity did not reuse Google's refill pool");
 c.MoneyBoostOnDestroy();a.MoneyBoostOnDestroy();a.MoneyBoostOnDestroy();check(BannerAdPreloader.destroys==2,"destroy not idempotent");
 System.out.println("BANNER PRELOADING PASS: official inventory, consent, start rollback, single registration, lazy poll, 30s visible rotation, hidden/background pause, no-fill retains current creative, stale paid guard, separate collapsible pool, no timed re-expansion, destroy.");}}
'''
